// Bullet Chart — Comparison, route: jsx
// Source: original:gaps/bullet-chart
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from bullet ----
// Five quarterly KPIs on deliberately different scales — each bullet row carries
// its own x scale, which is the chart's whole argument over a shared-axis bar.
// All measures read higher-is-better so the ascending poor/satisfactory/good
// bands mean the same thing on every row.
const quarterlyKpis: {
  name: string;
  value: number;
  target: number;
  ranges: [number, number, number];
}[] = [
  { name: 'Revenue ($M)', value: 275, target: 260, ranges: [200, 250, 300] },
  { name: 'New customers', value: 1650, target: 2000, ranges: [1200, 1800, 2400] },
  { name: 'Satisfaction (1–5)', value: 4.4, target: 4.5, ranges: [3.5, 4.25, 5] },
  { name: 'Avg order ($)', value: 320, target: 350, ranges: [250, 400, 600] },
  { name: 'On-time delivery (%)', value: 94, target: 96, ranges: [85, 92, 100] }
];

const ROW_HEIGHT = 46;
const BAND = 18;
const VALUE_BAR = 6;
const TICK_OVERHANG = 4;
const MARGIN = { top: 10, right: 56, bottom: 10, left: 128 };

// Graded context: poor darkest, good lightest, so the value bar reads on top of all three.
const BAND_OPACITY = [0.38, 0.24, 0.12];

const format = d3.format(',');

/**
 * One measure per row. `ranges` are the poor / satisfactory / good upper bounds in
 * ascending order; rows need not share units, because each row gets its own scale.
 */
export type Data = {
  name: string;
  value: number;
  target: number;
  ranges: [number, number, number];
}[];

export default function BulletChart({ data = quarterlyKpis, width }: { data?: Data; width: number }) {
  const innerWidth = Math.max(0, width - MARGIN.left - MARGIN.right);
  const height = data.length * ROW_HEIGHT + MARGIN.top + MARGIN.bottom;

  // One scale per row, built together: the measures are on different units, and the
  // per-row scale is what separates a bullet chart from a shared-axis bar chart.
  const scales = useMemo(
    () => data.map((d) => d3.scaleLinear().domain([0, d.ranges[2]]).range([0, innerWidth])),
    [data, innerWidth]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Bullet chart of five quarterly KPIs, each row showing its value bar and target tick against poor, satisfactory and good bands on its own scale"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {data.map((d, i) => {
          const x = scales[i];
          const middle = i * ROW_HEIGHT + ROW_HEIGHT / 2;
          return (
            <g key={d.name}>
              <text x={-10} y={middle} dy="0.32em" textAnchor="end" fontSize={11} fill="var(--text)">
                {d.name}
              </text>
              {d.ranges.map((upper, k) => {
                const lower = k === 0 ? 0 : x(d.ranges[k - 1]);
                return (
                  <rect
                    key={upper}
                    x={lower}
                    y={middle - BAND / 2}
                    width={Math.max(0, x(upper) - lower)}
                    height={BAND}
                    fill="var(--muted)"
                    fillOpacity={BAND_OPACITY[k]}
                  />
                );
              })}
              <rect
                x={0}
                y={middle - VALUE_BAR / 2}
                width={Math.max(0, x(d.value))}
                height={VALUE_BAR}
                fill="var(--accent)"
              />
              <line
                x1={x(d.target)}
                x2={x(d.target)}
                y1={middle - BAND / 2 - TICK_OVERHANG}
                y2={middle + BAND / 2 + TICK_OVERHANG}
                stroke="var(--text)"
                strokeWidth={2}
              />
              <text x={innerWidth + 8} y={middle} dy="0.32em" fontSize={10} fill="var(--text)">
                {format(d.value)}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}
